mapper.select:
select 
from edu_teacher_check_in r
where r.class_date = #{classDate}
and r.teacher_id = #{teacherId}
order by r.check_in_time

select 
from edu_teacher_check_in r
where r.class_date between #{start} and #{end}
and r.teacher_id = #{teacherId}
order by r.class_date, r.check_in_time

mapper.update:
update edu_teacher_check_in
check_in_time = #{checkInTime}, campus_name = #{campusName}, remark = #{remark},
where check_in_id = #{checkInId}
